def transform(grid):
    g = np.array(grid)
    bg = background(g)
    boxes = panels(g)
    ys = sorted(set(b[0] for b in boxes))
    xs = sorted(set(b[1] for b in boxes))
    out = g.copy()
    # collect marks: (colour, dy, dx) -> set of (panel_row, panel_col)
    marks = {}
    for b in boxes:
        y0, x0, y1, x1 = b
        pr, pc = ys.index(y0), xs.index(x0)
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                v = int(g[y, x])
                if v != bg:
                    marks.setdefault((v, y - y0, x - x0), set()).add((pr, pc))
    for (v, dy, dx), locs in marks.items():
        locs = list(locs)
        changed = False
        for (r1, c1) in locs:
            for (r2, c2) in locs:
                cells = []
                if r1 == r2 and c1 < c2:
                    cells = [(r1, c) for c in range(c1 + 1, c2)]
                elif c1 == c2 and r1 < r2:
                    cells = [(r, c1) for r in range(r1 + 1, r2)]
                for (r, c) in cells:
                    y, x = ys[r] + dy, xs[c] + dx
                    if out[y, x] != v:
                        out[y, x] = v
                        changed = True
        if changed:
            emit(out.copy(), f"Fill colour {v} at panel offset ({dy},{dx}) into panels lying between same-row/column panels that already have it")
    emit(out.copy(), "Final grid: all marks extended between aligned panels")
    return out
